Answer 1 - Triangular Generator

Helperssieve &lt;- function(n) {
  if (n &lt;= 3) {
    if (n &lt;= 1) return(NULL)
    if (n == 2) return(n)
    return(c(2, n))
  }
  # prime candidates
  x &lt;- rep(TRUE, n)
  # number 1 is not prime
  x[1] &lt;- FALSE
  i = 2
  n0 &lt;- floor(sqrt(n))
  for (i in 2:n0) {
    if (x[i]) {
      x[seq(i^2, n, i)] &lt;- FALSE
    }
  }
  return((1:n)[x])
}

prime.factors &lt;- function(n) {
  if (n &lt;= 1) return(NULL)
  # prime candidates
  p &lt;- sieve(floor(sqrt(n)))
  # prime factors
  p &lt;- p[which(n %% p == 0)]
  # only n is prime
  if (length(p) == 0) return(n)
  # stores n's factors 
  f &lt;- c()
  # get rest of prime factors
  for (i in p) {
    while (n %% i == 0) {
      f &lt;- c(f, i)
      n &lt;- n/i
    }
  }
  # gets highest last possible prime factor
  if (n &gt; 1) {
    f &lt;- c(f, n)
  }
  return(f)
}



Answertriangular.nd &lt;- function(n) {
  i &lt;- 1
  dn &lt;- 0
  while(dn &lt; n) {
    tr &lt;- i*(i+1)/2
    pn &lt;- prime.factors(tr) |&gt; table() |&gt; as.numeric()
    dn &lt;- prod(pn + 1)
    i &lt;- i+1
  }
  return(tr)
}

