Python
Answer 1 - Triangular Generator

Helpersdef sieve(n: float) -&gt; list:
  if n &lt;= 3:
    if n &lt;= 1: return([])
    if n == 2: return([n])
    return([2, n])
  n = int(n)
  # prime candidates
  x = [True] * n
  # number 1 is not prime
  x[0] = False
  n0 = int(n**0.5)
  for i in range(2, n0+1):
    if x[i-1]:
      for j in range(i**2, n+1, i):
        x[j-1] = False
  return([i for i, j in zip(list(range(1,n+1)), x) if j])

def prime_factors(n: int) -&gt; list:
  """
  Returns prime factorization of an integer
  """
  if (n &lt;= 1): return([])
  # prime candidates
  p = sieve(int(n**0.5))
  # prime factors
  p = [i for i in p if n % i == 0]
  # only n is prime
  if len(p) == 0: return([n])
  # stores n's factors 
  f = []
  # get rest of prime factors 
  for i in p:
    while(n % i == 0):
      f.append(i)
      n /= i
  if n &gt; 1:
    f.append(int(n))
  return(f)



Answerimport time
from math import prod
from collections import Counter

def triangular_nd(n: int) -&gt; int:
  i = 1
  dn = 0
  while(dn &lt; n):
    tr = i*(i+1)/2
    pn = list(Counter(prime_factors(tr)).values())
    dn = prod([i+1 for i in pn])
    i += 1
  return(tr)

t0 = time.perf_counter()
print(triangular_nd(500))
t1 = time.perf_counter()
t = t1 - t0
print(f'{t:.3f} sec elapsed')

