Answer 3 - Euclid’s Formula

Codefrom math import ceil, floor, prod

p = 1000
m1 = ceil(p**0.5/2)
m2 = floor((p/2)**0.5)
m = list(range(m1, m2+1))
# can use this because n = (p-2m^2)/(2m) & n is an integer
m = [i for i in m if (p-2*i**2) % (2*i) == 0][0]
n = (p-2*m**2)/(2*m)
# switch a & b here b/c 2mn &gt; m^2 - n^2 | they can be interchanged b/c a^2+b^2 = b^2+a^2 = c^2
d = {
  'a': 2 * m * n,
  'b': m**2 - n**2,
  'c': m**2 + n**2
}
print(d)
print(prod(d.values()))

